"""Reviewable V6 development checkpoint; never a claim of fresh validation."""
from pathlib import Path
from datetime import datetime,timezone
import json,html
ROOT=Path(__file__).resolve().parents[2];DEV=ROOT/'output/ml/gecco-v6-development';OUT=ROOT/'output/ml/gecco-v6'
def main():
    selected=json.loads((DEV/'run_04/results.json').read_text());tot=selected['overall']['totals'];b,c=tot['baseline'],tot['candidate']
    attempts=[]
    labels=['المسار المحلي الأول','الكبح المشروط بالتغير المحلي','منع تجزئة الإنذار واشتراط تغير فعلي','تأييد التغير المحلي بمصنّف شكل الحدث']
    for i,label in enumerate(labels,1):
        r=json.loads((DEV/f'run_{i:02d}/results.json').read_text());m=r['overall']['totals']['candidate'];a=r['v6_acceptance']
        attempts.append(f'<tr><td>{i}: {label}</td><td>{m["confirmed_new_alarm_inside_events"]}/104</td><td>{m["false_positive_runs"]}</td><td>{m["fp"]}</td><td>{m["f1"]:.4f}</td><td>{sum(r["overall"]["noninferior_periods"])}/13</td><td>{"اجتاز التطوير" if a["passes_development_requirements"] else "لم يجتز"}</td></tr>')
    period_rows=[]
    for folder in sorted((DEV/'run_04').iterdir()):
        p=folder/'results.json'
        if not folder.is_dir() or not p.exists():continue
        r=json.loads(p.read_text());left,right=r['baseline'],r['candidate']
        period_rows.append(f'<tr><td><a href="../gecco-v6-development/run_04/{folder.name}/results.json">{html.escape(folder.name)}</a></td><td>{left["confirmed_new_alarm_inside_events"]} → {right["confirmed_new_alarm_inside_events"]} / {left["true_events"]}</td><td>{left["false_positive_runs"]} → {right["false_positive_runs"]}</td><td>{left["fp"]} → {right["fp"]}</td><td>{len(r["lost_baseline_events"])}</td></tr>')
    generated=datetime.now(timezone.utc).isoformat()
    page=f'''<!doctype html><html lang="ar" dir="rtl"><meta charset="utf-8"><meta name="viewport" content="width=device-width, initial-scale=1"><title>مورد — تطوير V6</title><style>body{{font:18px/1.85 system-ui,sans-serif;background:#f3f6f5;color:#183432;max-width:1100px;margin:42px auto;padding:0 22px}}h1{{font-size:36px;line-height:1.5}}h2{{font-size:25px}}section{{background:white;border:1px solid #d8e2df;border-radius:18px;padding:25px;margin:22px 0}}.notice{{border-right:5px solid #b58b2d;background:#fffbef;padding:20px}}.cards{{display:grid;grid-template-columns:repeat(auto-fit,minmax(210px,1fr));gap:14px}}.card{{padding:16px;background:#e6f0ec;border-radius:12px}}strong.big{{display:block;font-size:27px;direction:ltr;unicode-bidi:isolate;white-space:nowrap}}td:nth-child(n+2){{direction:ltr;unicode-bidi:isolate;text-align:center}}table{{border-collapse:collapse;width:100%;font-size:15px}}th,td{{padding:12px;border-bottom:1px solid #dce5e1;text-align:right}}.scroll{{overflow:auto}}a{{color:#17655b}}small{{color:#536a65}}.ltr{{direction:ltr;display:inline-block}}</style>
    <p>مورد · كشف شذوذ الحساسات · V6</p><h1>تحسّن عبر فترات التطوير؛ الاختبار الجديد لم يبدأ بعد</h1>
    <p class="notice"><b>هذه نتائج تطوير على GECCO سبق الاطلاع عليها.</b> اختيرت الطريقة بعد أربع محاولات معلنة، لذلك لا تمثل هذه الأرقام اختبارًا مستقلًا. لم يتحقق هدف الاعتماد بعد، ولم يُربط النموذج بمحاكاة الـ3D. ستبقى بيانات WaterHub الجديدة مغلقة حتى تثبيت بروتوكول الاختبار كاملًا.</p>
    <div class="cards"><div class="card">الأحداث المكتشفة<strong class="big">{b['confirmed_new_alarm_inside_events']} → {c['confirmed_new_alarm_inside_events']}</strong>من أصل 104 أحداث؛ صفر أحداث سابقة مفقودة</div><div class="card">الإنذارات الكاذبة<strong class="big">236 → 168</strong>انخفاض {(1-c['false_positive_runs']/b['false_positive_runs'])*100:.1f}%</div><div class="card">دقائق الإنذار الكاذب<strong class="big">419 → 335</strong>انخفاض {(1-c['fp']/b['fp'])*100:.1f}%</div><div class="card">الفترات بلا تراجع<strong class="big">13 / 13</strong>تحسّن العدد في 6 فترات</div></div>
    <section><h2>ما الذي تغير؟</h2><p>أضيف كشف للقفزات والتغيرات المحلية حول التاريخ السابق لكل حساس. لا يُضاف إنذار من هذا المسار إلا بوجود تأييد من مصنّف شكل الحدث، وفق مرجع طبيعي من المعايرة السابقة. لا يتحول هذا المرجع إلى نسبة ثقة بسلامة الماء.</p><p>يمكن كبح إنذار النموذج الأساسي عندما تكون مؤشرات التغير المحلي ضمن المجال الطبيعي المتعلّم. بعد السماح بإنذار أساسي، يبقى حتى يزول إنذار النموذج الأساسي، لمنع تجزئته إلى عدة إنذارات. ولا يستمر إنذار المسار الإضافي بعد زوال الدليل الحالي. المعايرة تختبر الخرج النهائي وهوية كل حدث، لا عدد الأحداث وحده.</p><p>ارتفع F1 على مستوى العينات من <b>{b['f1']:.4f}</b> إلى <b>{c['f1']:.4f}</b>. ارتفع اكتشاف الأحداث من {100*b['confirmed_new_alarm_inside_events']/104:.1f}% إلى {100*c['confirmed_new_alarm_inside_events']/104:.1f}%؛ وهذه ليست «دقة النظام» أو دليل صلاحية ميدانية. لم يزد تأخر اكتشاف أي حدث سابق.</p></section>
    <section><h2>كل محاولات التطوير محفوظة</h2><div class="scroll"><table><thead><tr><th>المحاولة</th><th>الأحداث</th><th>إنذارات كاذبة</th><th>دقائق كاذبة</th><th>F1</th><th>بلا تراجع</th><th>القرار</th></tr></thead><tbody>{''.join(attempts)}</tbody></table></div><p>الفترات نفسها استُخدمت لتشخيص المحاولات وتطوير الطريقة؛ لا تُقدَّم المحاولة الرابعة كتحقق مستقل لمجرد أن تقسيمها زمني. داخل كل فترة، التدريب والمعايرة من الماضي، وتُحفظ الإعدادات قبل حساب تنبؤات الجزء التالي.</p></section>
    <section><h2>النتائج حسب الفترة: الأساسي → V6</h2><div class="scroll"><table><thead><tr><th>الفترة</th><th>الأحداث</th><th>الإنذارات الكاذبة</th><th>دقائقها</th><th>أحداث سابقة فُقدت</th></tr></thead><tbody>{''.join(period_rows)}</tbody></table></div><p>التحسن في اكتشاف الأحداث تحقق في 3 فترات، وانخفاض الإنذارات في 6 فترات. بقية الفترات لم تتراجع وفق شروط القبول. الأحداث تُحسب مرة واحدة على محور المصدر المستمر؛ لا تُمدَّد الوسوم ولا تُحسب جميع نقاط الحدث صحيحة بمجرد اكتشاف نقطة واحدة.</p></section>
    <section><h2>ما يلزم قبل اعتماد النتيجة؟</h2><p>المصدر الجديد المقترح WaterHub يمثل حساسات ضغط في معالجة مياه رمادية؛ لا يثبت كشف التلوث الكيميائي أو أصناف أعطال الحساس الخمسة. تم التحقق من تفسير الوسوم في كود الناشر، وبقيت قيم القياسات والوسوم الفعلية غير مفتوحة. يلزم إتمام اختبارات المحوّل، التعامل الصريح مع الوسوم المجهولة، وتثبيت الفترات الزمنية ومعيار القبول قبل الاختبار.</p><p>تبقى المنطقة الزمنية وتاريخ المعالجة قبل التصدير غير موثّقين بالكامل. لا يوجد اختبار Raspberry Pi أو توصيل صمام أو دمج 3D ضمن هذه النتيجة.</p><p><a href="../gecco-v6-development/selected_method.json">تثبيت الطريقة وسجل المحاولات</a> · <a href="../gecco-v6-development/run_04/results.json">النتائج الرقمية</a> · <a href="../gecco-v6-source-qualification/waterhub_source_semantics.json">توثيق المصدر الجديد</a> · <a href="../gecco-v5/report.html">تقرير V5 والاختبارات السابقة</a></p></section><small>تاريخ إنشاء التقرير: <span class="ltr">{generated}</span></small></html>'''
    OUT.mkdir(parents=True,exist_ok=True);(OUT/'report.html').write_text(page)
    (OUT/'status.json').write_text(json.dumps({'created_at_utc':generated,'selected_run':'run_04','development_acceptance':selected['v6_acceptance'],'goal_achieved':False,'fresh_source_measurements_or_labels_accessed':False,'three_d_connected':False,'next_required':'Freeze and execute independent WaterHub evaluation after source adapter, label accounting and runtime audit.'},indent=2)+'\n')
    print(OUT/'report.html')
if __name__=='__main__':main()
